def download_all():
    ok, failed = 0, []
    for i, (url, rel_path) in enumerate(IMAGES, 1):
        dest = os.path.join(OUTPUT_DIR, rel_path)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        if os.path.exists(dest):
            ok += 1
            continue
        try:
            r = requests.get(url, timeout=15, headers={"User-Agent": "Mozilla/5.0"})
            r.raise_for_status()
            with open(dest, "wb") as img:
                img.write(r.content)
            ok += 1
        except Exception as e:
            failed.append((url, rel_path, str(e)))
        if i % 25 == 0:
            print(f"{i}/{len(IMAGES)} traitées...")
        time.sleep(0.1)  # éviter de bombarder le site source

    print(f"\nTerminé : {ok} images OK, {len(failed)} échecs.")
    if failed:
        print("Échecs :")
        for url, rel_path, err in failed:
            print(f"  - {rel_path} <- {url} : {err}")

def write_sql():
    with open("update_image_urls.sql", "w", encoding="utf-8") as f:
        f.write("-- Généré par migrate_images.py — met à jour toutes les URLs\n")
        f.write("-- d'images vers le nouvel hébergement GitHub/jsDelivr.\n\n")
        for url, rel_path in IMAGES:
            new_url = f"{REPO_BASE_URL}/{rel_path}"
            url_esc = url.replace("'", "''")
            new_url_esc = new_url.replace("'", "''")
            if rel_path.startswith("sets/"):
                f.write(f"update pieces set image_url = '{new_url_esc}' where image_url = '{url_esc}';\n")
            else:
                f.write(f"update commemorative_coins set image_url = '{new_url_esc}' where image_url = '{url_esc}';\n")
    print("Fichier update_image_urls.sql généré.")

if __name__ == "__main__":
    download_all()
    write_sql()
